mapper.select:
SELECT p.id, p.generation_id AS generationId, p.user_id AS userId, p.title, p.image_url AS imageUrl, p.thumbnail_url AS thumbnailUrl, p.keyword, p.style, p.elements, p.color_theme AS colorTheme, p.usage_scene AS usageScene, p.description, p.is_saved AS isSaved, p.is_favorite AS isFavorite, p.is_recommend AS isRecommend, p.view_count AS viewCount, p.like_count AS likeCount, p.use_count AS useCount, p.status, DATE_FORMAT(p.created_at, '%Y-%m-%d %H:%i:%s') AS createdAt, DATE_FORMAT(p.updated_at, '%Y-%m-%d %H:%i:%s') AS updatedAt, u.nickname AS userNickname FROM pattern p LEFT JOIN user u ON p.user_id = u.id WHERE p.deleted = 0
AND p.user_id = #{userId}
AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.keyword LIKE CONCAT('%', #{keyword}, '%'))
AND p.style = #{style}
AND p.status = #{status}
AND p.is_recommend = #{isRecommend}
ORDER BY p.updated_at DESC
